/**
 * Release checksum manifest (audit P2-18).
 *
 * The release workflow publishes unsigned binaries, so SHA256SUMS.txt is the
 * only way a user can tie a download to a build. It is generated by
 * scripts/sha256sums.mjs rather than by shell tooling because macOS runners ship
 * `shasum -a 256` (not `sha256sum`), BSD sort/xargs lack `-z`/`-0`, and artifact
 * names contain spaces, which plain xargs would split.
 *
 * The tests drive the script as a child process rather than importing it: a
 * Windows checkout with core.autocrlf=true materialises the .mjs with CRLF, and
 * Vite's transform of a CRLF .mjs fails with "Invalid or unexpected token". Going
 * through the CLI is also closer to how the workflow uses it.
 */
import { execFile } from 'node:child_process'
import { createHash } from 'node:crypto'
import { mkdir, mkdtemp, readFile, writeFile } from 'node:fs/promises'
import os from 'node:os'
import path from 'node:path'
import { promisify } from 'node:util'
import { beforeEach, describe, expect, it } from 'vitest'

const execFileAsync = promisify(execFile)
const SCRIPT = path.join(process.cwd(), 'scripts', 'sha256sums.mjs')
const MANIFEST = 'SHA256SUMS.txt'

let dir = ''

beforeEach(async () => {
  dir = await mkdtemp(path.join(os.tmpdir(), 'ipatool-sums-'))
})

function sha256(data: string): string {
  return createHash('sha256').update(data).digest('hex')
}

/** Runs the script and returns its stdout/stderr/exit code. */
async function run(args: string[]): Promise<{ code: number; stdout: string; stderr: string }> {
  try {
    const { stdout, stderr } = await execFileAsync(process.execPath, [SCRIPT, ...args])
    return { code: 0, stdout, stderr }
  } catch (error) {
    const failure = error as { code?: number; stdout?: string; stderr?: string }
    return { code: failure.code ?? 1, stdout: failure.stdout ?? '', stderr: failure.stderr ?? '' }
  }
}

async function manifestLines(): Promise<string[]> {
  const text = await readFile(path.join(dir, MANIFEST), 'utf8')
  return text.trimEnd().split('\n')
}

describe('artifact selection', () => {
  it('checksums every shipped installer type', async () => {
    const artifacts = [
      'ipatool-gui-0.1.1-win-x64-setup.exe',
      'ipatool-gui-0.1.1-win-x64-portable.exe',
      'ipatool-gui-0.1.1-mac-arm64.app.tar.gz',
      'ipatool-gui-0.1.1-linux-x86_64.AppImage',
      'ipatool-gui-0.1.1-linux-amd64.deb',
      'ipatool-gui-0.1.1-mac-x64.dmg'
    ]
    for (const name of artifacts) await writeFile(path.join(dir, name), name)

    const result = await run([dir])
    expect(result.code).toBe(0)
    expect(result.stdout).toContain('6 artifact(s)')

    const lines = await manifestLines()
    expect(lines).toHaveLength(6)
    // Sorted, so the manifest is stable across runs and diffable.
    expect(lines.map((line) => line.slice(66))).toEqual([...artifacts].sort())
  })

  it('ignores build leftovers and the manifest itself', async () => {
    await writeFile(path.join(dir, 'a.exe'), 'a')
    for (const name of [
      'builder-effective-config.yaml',
      'latest.yml',
      'ipatool-gui-0.1.1-win-x64-setup.exe.blockmap'
    ]) {
      await writeFile(path.join(dir, name), 'ignored')
    }

    await run([dir])
    const lines = await manifestLines()
    expect(lines).toHaveLength(1)
    expect(lines[0]).toMatch(/a\.exe$/)
  })

  it('skips a directory whose name matches an extension', async () => {
    await mkdir(path.join(dir, 'weird.AppImage'))
    await writeFile(path.join(dir, 'real.AppImage'), 'x')

    await run([dir])
    const lines = await manifestLines()
    expect(lines).toHaveLength(1)
    expect(lines[0]).toMatch(/real\.AppImage$/)
  })
})

describe('manifest format', () => {
  it('matches the "sha256sum -c" format exactly', async () => {
    await writeFile(path.join(dir, 'x.deb'), 'installer bytes')
    await run([dir])

    const [line] = await manifestLines()
    // Two spaces is the separator sha256sum expects; one space means text mode.
    expect(line).toMatch(/^[0-9a-f]{64} {2}x\.deb$/)
    expect(line!.startsWith(sha256('installer bytes'))).toBe(true)
  })

  it('is idempotent and never lists itself', async () => {
    await writeFile(path.join(dir, 'a.exe'), 'a')
    await run([dir])
    const first = await manifestLines()
    await run([dir])
    const second = await manifestLines()

    expect(second).toEqual(first)
    expect(second.join('\n')).not.toContain(MANIFEST)
  })
})

describe('failure modes', () => {
  it('exits non-zero with ::error:: when there is nothing to checksum', async () => {
    // A green run here would publish a release nobody can verify.
    const result = await run([dir])
    expect(result.code).toBe(1)
    expect(result.stderr).toContain('::error::no release artifacts to checksum')
    await expect(readFile(path.join(dir, MANIFEST), 'utf8')).rejects.toThrow()
  })

  it('reports a missing directory as an annotated error, not a stack trace', async () => {
    const missing = path.join(dir, 'nope')
    const result = await run([missing])

    expect(result.code).toBe(1)
    expect(result.stderr).toContain('::error::cannot checksum')
    expect(result.stderr).toContain(missing)
    // No raw stack trace: the workflow annotation is the whole message.
    expect(result.stderr).not.toContain('at async')
  })
})
